const DOOD = [['squiggle', 'Squiggle', [[-46, 0], [-34, -16], [-22, 10], [-10, -14], [2, 10], [14, -14], [26, 10], [38, -12], [46, 4]]], ['swirl', 'Swirl', (() => { const p = []; for (let t = 0; t < 14; t += 0.3) p.push([Math.cos(t) * t * 3.2, Math.sin(t) * t * 3.2]); return p; })()], ['loops', 'Loops', (() => { const p = []; for (let t = 0; t < TAU * 4; t += 0.25) p.push([-40 + t * 3.2 + Math.cos(t) * 10, Math.sin(t) * 14]); return p; })()], ['circlemark', 'Circled', (() => { const p = []; for (let t = 0; t < TAU * 1.15; t += 0.2) p.push([Math.cos(t) * 46, Math.sin(t) * 26]); return p; })()], ['underline', 'Underline', [[-46, 6], [-10, 0], [20, 4], [46, -2], [-30, 10], [30, 8]]], ['zig', 'Zig doodle', [[-46, 10], [-30, -10], [-14, 10], [2, -10], [18, 10], [34, -10], [46, 6]]], ['spiral', 'Spiral', (() => { const p = []; for (let t = 0; t < 18; t += 0.25) p.push([Math.cos(t) * (46 - t * 2.4), Math.sin(t) * (46 - t * 2.4)]); return p; })()], ['arrowdoodle', 'Doodle arrow', [[-44, 20], [-20, -4], [6, 10], [30, -14], [40, -20], [28, -20], [40, -20], [38, -8]]]];
