for (const w of ['POW!', 'BOOM!', 'ZAP!', 'WOW!']) add('comic', w.toLowerCase().replace('!', ''), w + ' burst', 'comic burst sound effect ' + w, (g, A, B) => burstText(g, A, B, w, w.length > 4 ? 14 : 11));
