add('comic', 'actionlines', 'Action lines', 'motion lines comic', (g, A) => { for (let i = 0; i < 7; i++) { const y = -36 + i * 12, l = 30 + (i * 37) % 50; P.rr(g, -48, y, l, 4, 2); F(g, A); } }, 0.8);
add('comic', 'sweat', 'Sweat drop', 'sweat drop manga anime', (g, A) => { P.drop(g, 0, 0, 90); F(g, A); P.circ(g, -8, 6, 6); F(g, 'rgba(255,255,255,0.7)'); });
add('comic', 'anger', 'Anger mark', 'anger vein manga', (g, A) => { for (let i = 0; i < 4; i++) { g.save(); g.rotate(i * Math.PI / 2); g.beginPath(); g.moveTo(8, -8); g.quadraticCurveTo(10, -36, 30, -40); g.moveTo(8, -8); g.quadraticCurveTo(36, -10, 40, -30); S(g, A, 7); g.restore(); } });
add('comic', 'jagged', 'Shout bubble', 'speech bubble shout', (g, A, B) => { P.star(g, 14, 48, 34); F(g, A); P.star(g, 14, 48, 34); S(g, B, 3); });
add('comic', 'thought', 'Thought bubble', 'thought bubble think', (g, A, B) => { P.cloud(g, 6, -8, 86, 0); F(g, A); P.circ(g, -30, 30, 7); F(g, A); P.circ(g, -40, 42, 4); F(g, A); P.cloud(g, 6, -8, 86, 0); S(g, B, 2.5); });
add('comic', 'mangasparkle', 'Manga sparkle', 'sparkle shine anime', (g, A) => { for (const [x, y, s] of [[-14, -10, 30], [22, 18, 16], [24, -26, 10]]) { g.beginPath(); g.moveTo(x, y - s); g.lineTo(x + s * 0.18, y - s * 0.18); g.lineTo(x + s, y); g.lineTo(x + s * 0.18, y + s * 0.18); g.lineTo(x, y + s); g.lineTo(x - s * 0.18, y + s * 0.18); g.lineTo(x - s, y); g.lineTo(x - s * 0.18, y - s * 0.18); g.closePath(); F(g, A); } });
