add('sound', 'staff', 'Music staff', 'staff stave sheet music', (g, A) => { for (let y = -16; y <= 16; y += 8) { g.fillStyle = A; g.fillRect(-48, y, 96, 1.6); } P.circ(g, -20, 8, 5.5); F(g, A); g.fillRect(-15.5, -26, 2, 34); P.circ(g, 10, -4, 5.5); F(g, A); g.fillRect(14.5, -36, 2, 32); }, 0.6);
add('sound', 'notescatter', 'Floating notes', 'notes music floating', (g, A, B) => { for (const [x, y, s, c] of [[-26, 10, 1, A], [12, -14, 0.8, B], [30, 22, 0.6, A]]) { g.save(); g.translate(x, y); g.scale(s * 0.6, s * 0.6); P.circ(g, -12, 28, 15); F(g, c); g.fillStyle = c; g.fillRect(0, -44, 6, 72); g.beginPath(); g.moveTo(6, -44); g.quadraticCurveTo(30, -36, 26, -8); g.quadraticCurveTo(22, -28, 6, -26); g.fill(); g.restore(); } });
add('sound', 'metronome', 'Metronome', 'metronome tempo bpm', (g, A, B) => { P.poly(g, [[-14, -44], [14, -44], [30, 44], [-30, 44]]); F(g, A); g.beginPath(); g.moveTo(0, 30); g.lineTo(18, -34); S(g, B, 4); P.rr(g, 8, -14, 14, 8, 2); F(g, B); });
