add('badges', 'shieldbadge', 'Crest badge', 'crest emblem badge', (g, A, B) => { g.beginPath(); g.moveTo(-36, -40); g.lineTo(36, -40); g.lineTo(36, 4); g.quadraticCurveTo(36, 34, 0, 48); g.quadraticCurveTo(-36, 34, -36, 4); g.closePath(); F(g, A); g.beginPath(); g.moveTo(-28, -32); g.lineTo(28, -32); g.lineTo(28, 2); g.quadraticCurveTo(28, 26, 0, 38); g.quadraticCurveTo(-28, 26, -28, 2); g.closePath(); S(g, B, 3); });
