for (let v = 0; v < 4; v++) add('abstract', 'blob' + v, 'Blob ' + (v + 1), 'blob organic shape', (g, A) => { const r = rng(80 + v); g.beginPath(); const n = 7, pts = []; for (let i = 0; i < n; i++) { const a = i / n * TAU; pts.push([Math.cos(a) * (30 + r() * 18), Math.sin(a) * (30 + r() * 18)]); } for (let i = 0; i < n; i++) { const p = pts[i], q = pts[(i + 1) % n]; const m = [(p[0] + q[0]) / 2, (p[1] + q[1]) / 2]; if (!i) g.moveTo(m[0], m[1]); const q2 = pts[(i + 1) % n], m2 = [(q2[0] + pts[(i + 2) % n][0]) / 2, (q2[1] + pts[(i + 2) % n][1]) / 2]; g.quadraticCurveTo(q2[0], q2[1], m2[0], m2[1]); } g.closePath(); F(g, A); });
for (let v = 0; v < 3; v++) add('abstract', 'brush' + v, 'Brush stroke ' + (v + 1), 'brush stroke paint', (g, A) => { const r = rng(90 + v); g.beginPath(); g.moveTo(-48, 6); for (let x = -48; x <= 48; x += 4) g.lineTo(x, -14 + Math.sin(x / 20 + v) * 6 + (r() - 0.5) * 5); for (let x = 48; x >= -48; x -= 4) g.lineTo(x, 14 + Math.sin(x / 20 + v) * 6 + (r() - 0.5) * 5); g.closePath(); F(g, A); for (let i = 0; i < 6; i++) { g.globalCompositeOperation = 'destination-out'; g.fillRect(-48 + r() * 96, -18 + r() * 36, 10 + r() * 20, 1.2); } g.globalCompositeOperation = 'source-over'; }, 0.5);
add('abstract', 'splash', 'Paint splash', 'paint splash', (g, A) => { const r = rng(97); g.beginPath(); for (let i = 0; i <= 26; i++) { const a = i / 26 * TAU, R = i % 2 ? 22 + r() * 8 : 34 + r() * 16; g.lineTo(Math.cos(a) * R, Math.sin(a) * R); } g.closePath(); F(g, A); for (let i = 0; i < 6; i++) { const a = r() * TAU; P.circ(g, Math.cos(a) * 46, Math.sin(a) * 46, 2 + r() * 3); F(g, A); } });
add('abstract', 'orb', 'Gradient orb', 'gradient orb sphere', (g, A, B) => { const gr = g.createLinearGradient(-40, -40, 40, 40); gr.addColorStop(0, A); gr.addColorStop(1, B); P.circ(g, 0, 0, 46); g.fillStyle = gr; g.fill(); });
add('abstract', 'liquid', 'Liquid shape', 'liquid fluid', (g, A, B) => { const gr = g.createLinearGradient(0, -46, 0, 46); gr.addColorStop(0, A); gr.addColorStop(1, B); g.beginPath(); g.moveTo(-40, -30); g.bezierCurveTo(-10, -60, 30, -10, 44, -30); g.bezierCurveTo(56, 10, 20, 50, -6, 40); g.bezierCurveTo(-40, 30, -60, 0, -40, -30); g.fillStyle = gr; g.fill(); });
add('abstract', 'stripesorb', 'Striped circle', 'stripes circle abstract', (g, A, B) => { g.save(); P.circ(g, 0, 0, 46); g.clip(); g.fillStyle = A; g.fillRect(-50, -50, 100, 100); g.fillStyle = B; for (let y = -50; y < 50; y += 10) g.fillRect(-50, y, 100, 5); g.restore(); });
add('abstract', 'squiggleshape', 'Memphis squiggle', 'memphis squiggle 80s', (g, A) => { g.beginPath(); for (let x = -46; x <= 46; x += 2) g.lineTo(x, Math.sin(x / 7) * 12); S(g, A, 9); }, 0.5);
